def pexels_photo(page_url, slug):
    out = ROOT/'assets'/'covers'
    out.mkdir(parents=True, exist_ok=True)
    m = re.search(r'(\d+)/?$', page_url)
    if not m:
        raise RuntimeError(page_url)
    pid=m.group(1)
    candidates=[f'https://images.pexels.com/photos/{pid}/pexels-photo-{pid}.jpeg?auto=compress&cs=tinysrgb&w=2200']
    req=urllib.request.Request(page_url,headers={'User-Agent':'Mozilla/5.0'})
    try:
        page=urllib.request.urlopen(req,timeout=20).read().decode('utf-8','ignore')
        mm=re.search(r'<meta[^>]+property=["\']og:image["\'][^>]+content=["\']([^"\']+)',page,re.I)
        if not mm:
            mm=re.search(r'<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']og:image["\']',page,re.I)
        if mm: candidates.insert(0,html.unescape(mm.group(1)))
    except Exception:
        pass
    data=None
    for u in candidates:
        try:
            rr=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0'})
            data=urllib.request.urlopen(rr,timeout=30).read()
            if len(data)>10000: break
        except Exception:
            data=None
    if not data: raise RuntimeError('image download failed '+page_url)
    img=Image.open(io.BytesIO(data)).convert('RGB')
    specs=[('16x9',1600,900),('4x3',1200,900),('1x1',1200,1200)]
    for label,w,h in specs:
        ratio=w/h; ir=img.width/img.height
        if ir>ratio:
            nh=img.height; nw=int(nh*ratio); left=(img.width-nw)//2; crop=img.crop((left,0,left+nw,nh))
        else:
            nw=img.width; nh=int(nw/ratio); top=(img.height-nh)//2; crop=img.crop((0,top,nw,top+nh))
        crop=crop.resize((w,h),Image.Resampling.LANCZOS)
        crop.save(out/f'{slug}-{label}.jpg','JPEG',quality=84,optimize=True,progressive=True)


def recipe_schema(a, canonical, images):
    if a['type']!='Recipe': return None
    return {
      '@context':'https://schema.org','@type':'Recipe','name':a['title'],'description':a['description'],
      'image':images,'datePublished':a['publishedAt'],'dateModified':a['updatedAt'],
      'author':{'@type':'Person','name':a['author'],'url':f"{SITE}/author-{AUTHORS[a['author']]['slug']}.html"},
      'recipeYield':a['yield'],'totalTime':a['time'],'recipeCategory':'Сезонные рецепты',
      'recipeIngredient':a['ingredients'],'recipeInstructions':[{'@type':'HowToStep','text':x} for x in a['steps']],
      'mainEntityOfPage':{'@type':'WebPage','@id':canonical},'inLanguage':'ru-RU'
    }


