    slug=a['slug']; canonical=f'{SITE}/articles/{slug}.html'; author=AUTHORS[a['author']]
    images=[f'{SITE}/assets/covers/{slug}-16x9.jpg',f'{SITE}/assets/covers/{slug}-4x3.jpg',f'{SITE}/assets/covers/{slug}-1x1.jpg']
    if a['type']=='Recipe':
        schema=recipe_schema(a,canonical,images)
        ing='<h2>Что понадобится</h2><ul>'+''.join(f'<li>{html.escape(x)}</li>' for x in a['ingredients'])+'</ul>'
        steps='<h2>Как приготовить</h2><ol>'+''.join(f'<li>{html.escape(x)}</li>' for x in a['steps'])+'</ol>'
